import React from "react";
import NewTaskForm from "../new-task-form";
import TaskList from "../task-list";
import Footer from "../footer";
import "./app.css";

class App extends React.Component {
  maxId = 100;
  state = {
    todoData: [
      this.createTask("task №1"),
      this.createTask("task №2"),
      this.createTask("task №3"),
    ],
    tab: "all",
  };
  onMarkComplete = (id) => {
    this.setState(({ todoData }) => {
      const index = todoData.findIndex((el) => el.id === id);
      const oldItem = todoData[index];

      const newCondition =
        oldItem.condition === "completed" ? "active" : "completed";
      const newItem = { ...oldItem, condition: newCondition };

      const newArray = [
        ...todoData.slice(0, index),
        newItem,
        ...todoData.slice(index + 1),
      ];
      return {
        todoData: newArray,
      };
    });
  };
  onDelete = (id) => {
    this.setState(({ todoData }) => {
      const index = todoData.findIndex((el) => el.id === id);
      const newArray = [
        ...todoData.slice(0, index),
        ...todoData.slice(index + 1),
      ];

      return {
        todoData: newArray,
      };
    });
  };
  onAdd = (text) => {
    const item = this.createTask(text);
    this.setState(({ todoData }) => {
      const newArray = [item, ...todoData];
      return {
        todoData: newArray,
      };
    });
  };
  onTab = (name) => {
    this.setState({
      tab: name,
    });
  };
  onDeleteCompleted = () => {
    this.setState(({ todoData }) => {
      const newArray = todoData.filter(
        (item) => item.condition !== "completed"
      );
      return {
        todoData: newArray,
      };
    });
  };

  createTask(text) {
    return {
      condition: "active",
      text,
      id: this.maxId++,
      time: new Date()
    };
  }

  render() {
    return (
      <section className="todoapp">
        <NewTaskForm add={this.onAdd} />
        <section className="main">
          <TaskList
            {...this.state}
            markComplete={this.onMarkComplete}
            del={this.onDelete}
          />
          <Footer
            {...this.state}
            onTab={this.onTab}
            deleteCompleted={this.onDeleteCompleted}
          />
        </section>
      </section>
    );
  }
}

export default App;
